INSERT INTO public.engagement_messages(id,title,body) VALUES
('tip-001','🏢 مش مجرد دفتر إلكتروني','العمارة بيجمع الاشتراكات والمصروفات والتقارير في نظام واحد، بدل ما كل معلومة تبقى في مكان.'),
('tip-002','💰 كل جنيه له حكاية','تابع التحصيلات والمصروفات ورصيد الخزينة بصورة أوضح من داخل العمارة.'),
('tip-003','📊 الأرقام لما تتنظم','تقرير واضح يوفّر وقت طويل من مراجعة الدفاتر والحسابات اليدوية.'),
('tip-004','🗳️ القرار مش لشخص واحد','الاستفتاءات بتخلي مشاركة السكان في قرارات العمارة أسهل.'),
('tip-005','🔔 خبر الصيانة يوصل','إعلان واحد من الإدارة يساعد السكان يعرفوا المستجدات في وقتها.'),
('tip-006','📱 عمارتك معاك','مش لازم تكون واقف قدام دفتر الحسابات علشان تتابع شؤون العمارة.'),
('tip-007','✨ التفاصيل الصغيرة بتفرق','من بيانات الشقق لجهات الصيانة، العمارة بيخلّي المعلومات المهمة قريبة.'),
('tip-008','🧾 من أول شهر لحد النهارده','حتى الحسابات القديمة ليها مكان في نظام منظم للمتابعة.'),
('tip-009','🤝 إدارة وسكان على نفس الصفحة','تواصل أوضح وإعلانات منظمة بدل الرسائل المتفرقة.'),
('tip-010','🔧 رقم الفني وقت الحاجة','خلي بيانات جهات الصيانة متاحة بدل البحث عنها كل مرة.'),
('tip-011','🏠 كل شقة ليها حسابها','متابعة الاشتراكات حسب الشقة تساعد الإدارة تشوف الصورة كاملة.'),
('tip-012','📣 الإعلان اللي يهمك','تابع أخبار العمارة وإعلانات الإدارة من مكان واحد.'),
('tip-013','💡 الإدارة الذكية تبدأ من هنا','العمارة مش بس لتسجيل المدفوعات؛ ده لتنظيم شؤون العقار يومًا بيوم.'),
('tip-014','📈 الصورة المالية أوضح','اعرف حركة الخزينة والتحصيلات بدل الاعتماد على التقديرات.'),
('tip-015','🧠 أقل ورق.. تنظيم أكتر','خلي السجلات والتقارير في مكان يسهل الرجوع له.'),
('tip-016','👀 فاتك إعلان مهم؟','راجع إعلانات العمارة علشان تعرف آخر المستجدات.'),
('tip-017','🛠️ الصيانة مش مجرد بلاغ','متابعة أخبار الصيانة بتساعد السكان والإدارة يكونوا على علم.'),
('tip-018','💬 رأيك ممكن يغيّر قرار','شارك في استفتاءات عمارتك لما الإدارة تطرح موضوعًا للتصويت.'),
('tip-019','🏙️ لكل عمارة نظامها','بيانات كل عقار وحساباته مستقلة علشان الإدارة تفضل منظمة.'),
('tip-020','🌟 فرق كبير في التفاصيل','بدل ملفات متفرقة، متابعة الاشتراكات والمصروفات في تطبيق واحد.'),
('tip-021','📋 تقرير بدل ساعات مراجعة','اختار الفترة اللي محتاجها وراجع بيانات العمارة بصورة منظمة.'),
('tip-022','🔍 الشفافية تبدأ بالمعلومة','لما الحسابات تتسجل بوضوح، مراجعتها تبقى أسهل.'),
('tip-023','🚪 مدير العمارة مش لوحده','العمارة بيساعد الإدارة والسكان يتابعوا الأخبار والتفاصيل المناسبة لكل دور.'),
('tip-024','💎 نظام معمول للعمارات','مش تطبيق حسابات عام؛ العمارة مصمم لاحتياجات إدارة العقارات والسكان.'),
('tip-025','⏳ وقتك أغلى من الدفاتر','سجّل المدفوعات والمصروفات في مكان واحد وارجع لها وقت ما تحتاج.'),
('tip-026','🎯 من غير لخبطة','تنظيم الشقق والتحصيلات بيسهّل المتابعة الشهرية.'),
('tip-027','📲 رسالة واحدة تكفي','بدل تكرار نفس الخبر لكل ساكن، استخدم إعلانات العمارة.'),
('tip-028','🧮 الحسابات مش تخمين','رصيد الخزينة بيعكس التحصيلات والمصروفات المسجلة.'),
('tip-029','🌱 عمارة منظمة.. يوم أهدى','كل خطوة في التنظيم بتسهّل التواصل والمتابعة بين الجيران.'),
